create table public.feedbacks (
    "id" bigint generated by default as identity not null,
    "user_id" uuid references auth.users on delete
    set null default auth.uid(),
        "title" text not null,
        "content" text not null,
        "created_at" timestamp with time zone default current_timestamp
);
--  _____             _ _                _      ____       _ _      _           
-- |  ___|__  ___  __| | |__   __ _  ___| | __ |  _ \ ___ | (_) ___(_) ___  ___ 
-- | |_ / _ \/ _ \/ _` | '_ \ / _` |/ __| |/ / | |_) / _ \| | |/ __| |/ _ \/ __|
-- |  _|  __/  __/ (_| | |_) | (_| | (__|   <  |  __/ (_) | | | (__| |  __/\__ \
-- |_|  \___|\___|\__,_|_.__/ \__,_|\___|_|\_\ |_|   \___/|_|_|\___|_|\___||___/
revoke
update,
    delete,
    select on table "public"."feedbacks"
from anon,
    authenticated;
alter table "public"."feedbacks" enable row level security;
create policy "Enable insert for users based on user_id" on "public"."feedbacks" as PERMISSIVE for
INSERT to public with check (
        (
            select auth.uid()
        ) = user_id
    );